<?php
declare(strict_types=1);
require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../includes/auth.php'; require_role('teacher');
$user=current_user();$pdo=db();$courseId=(int)($_GET['course_id']??0);
$sql="SELECT a.*,c.title course_title,c.course_code, q.id quiz_id FROM activities a JOIN courses c ON c.id=a.course_id JOIN teacher_courses tc ON tc.course_id=c.id LEFT JOIN quizzes q ON (q.activity_id=a.id OR (q.activity_id IS NULL AND q.course_id=a.course_id AND q.title=a.title)) WHERE tc.teacher_id=?";
$params=[$user['id']]; if($courseId){$sql.=" AND c.id=?";$params[]=$courseId;} $sql.=" ORDER BY c.title,a.created_at DESC";
$stmt=$pdo->prepare($sql);$stmt->execute($params);$activities=$stmt->fetchAll();
$page_title='Activities';require __DIR__.'/../includes/header.php';
$labels=['assignment'=>'Assignment','quiz'=>'Quiz','project'=>'Project','practical'=>'Practical Activity','discussion'=>'Discussion / Task'];
$icons=['assignment'=>'fa-file-pen','quiz'=>'fa-circle-question','project'=>'fa-diagram-project','practical'=>'fa-flask','discussion'=>'fa-comments'];
